import pLimit, {limitFunction} from './index.js';

const turn = () => new Promise(resolve => {
	setImmediate(resolve);
});

const verifyCompletionReaction = async wrapped => {
	const first = Promise.withResolvers();
	const second = Promise.withResolvers();
	let followUp;
	let reported = false;
	const limit = wrapped
		? limitFunction(which => which === 0 ? first.promise : second.promise, {concurrency: 1})
		: pLimit(1);
	const invoke = which => wrapped
		? limit(which)
		: limit(() => which === 0 ? first.promise : second.promise);
	try {
		const initial = invoke(0);
		// Register the actual consumer reaction before the idle waiter.
		const enqueued = initial.then(() => { // eslint-disable-line promise/prefer-await-to-then
			followUp = invoke(1);
		});
		const idle = limit.onIdle().then(() => { // eslint-disable-line promise/prefer-await-to-then
			reported = true;
		});
		await turn();
		assert.equal(reported, false);
		first.resolve();
		await enqueued;
		await turn();
		assert.equal(reported, false, 'onIdle reported while the completion reaction job was held');
		second.resolve();
		await followUp;
		await idle;
		assert.equal(reported, true);
	} finally {
		first.resolve();
		second.resolve();
	}
};

test('limiter completion reaction does not report idle early', {timeout: 4000}, async () => {
	await verifyCompletionReaction(false);
});

test('wrapper completion reaction does not report idle early', {timeout: 4000}, async () => {
	await verifyCompletionReaction(true);
